// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const data = $input.first().json;

if (!data.articles || data.articles.length === 0) {
  throw new Error("Aucun article reçu, arrêt du workflow.");
}

const cleanArticles = data.articles.map(a => ({
  article_id: a.article_id,
  title: a.title || "Sans titre",
  source: a.source || "Source inconnue",
  original_url: a.original_url,
  category: a.category || "Général",
  summary: a.summary || "",
  publication_date: a.publication_date
}));

return [{ json: { ...data, articles: cleanArticles } }];

const data = $input.first().json;
const newsletterId = data.newsletter_id;

const articlesWithTracking = data.articles.map(article => {
  const utm = `utm_source=newsletter&utm_medium=email&utm_campaign=${newsletterId}&utm_content=${article.article_id}`;
  const separator = article.original_url.includes('?') ? '&' : '?';
  return {
    ...article,
    tracking_url: `${article.original_url}${separator}${utm}`
  };
});

return [{ json: { ...data, articles: articlesWithTracking } }];
